function n(t){if(!t)return"—";const e=Math.floor((Date.now()-new Date(t).getTime())/864e5);return e<=0?"today":e===1?"1 day ago":`${e} days ago`}function a(t){if(!t)return"—";const e=Math.floor((Date.now()-new Date(t).getTime())/6e4);if(e<60)return`${e}m ago`;const r=Math.floor(e/60);if(r<24)return`${r}h ago`;const o=Math.floor(r/24);return o===1?"Yesterday":`${o}d ago`}function i(t){if(!t)return"—";const e=Math.floor((Date.now()-new Date(t).getTime())/864e5);if(e>1)return`${e} days overdue`;if(e===1)return"1 day overdue";if(e===0)return"today";const r=Math.abs(e);return r===1?"tomorrow":`in ${r} days`}export{a,i as d,n as t};
